#[cfg(test)]
mod perf_probe {
    use std::time::{Duration, Instant};

    use gpui_kit::component::Root;
    use gpui_kit::{AppContext as _, TestAppContext};

    use super::{HarnessEvent, PromptMode};
    use crate::piton_syntax;
    use crate::project_directory::ProjectDirectory;

    fn tool(id: &str, name: &str) -> HarnessEvent {
        HarnessEvent::ToolStarted { id: id.into(), name: name.into() }
    }

    #[gpui_kit::test]
    #[ignore]
    async fn probe(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
        });
        let mut pm = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| PromptMode::new(window, cx));
            pm = Some(view.clone());
            Root::new(view, window, cx)
        });
        let pm = pm.unwrap();
        let handle: gpui_kit::AnyWindowHandle = window.into();
        let frame_time = |cx: &mut TestAppContext, notify: bool| {
            let mut total = Duration::ZERO;
            for _ in 0..10 {
                cx.update_window(handle, |_, window, cx| {
                    if notify {
                        pm.update(cx, |_, cx| cx.notify());
                    } else {
                        window.refresh();
                    }
                    let start = Instant::now();
                    window.draw(cx);
                    total += start.elapsed();
                })
                .unwrap();
            }
            total / 10
        };
        for rows in [10usize, 100, 400] {
            cx.update_window(handle, |_, _, cx| {
                pm.update(cx, |this, cx| {
                    this.tasks.clear();
                    let ix = this.push_task("Do it".into(), cx);
                    for n in 0..rows {
                        if n % 2 == 0 {
                            this.apply_event(ix, HarnessEvent::TextStarted, cx);
                            this.apply_event(ix, HarnessEvent::TextDelta(format!("Paragraph {n} with **some** markdown `code` and a longer sentence to wrap across the view. ").repeat(3)), cx);
                        } else {
                            this.apply_event(ix, tool(&format!("t{n}"), "Read"), cx);
                            this.apply_event(ix, HarnessEvent::ToolInput { id: format!("t{n}"), summary: format!("src/file_{n}.rs") }, cx);
                        }
                    }
                });
            })
            .unwrap();
            frame_time(cx, false);
            eprintln!("PROBE output rows={rows}: frame {:?}", frame_time(cx, true));
        }
    }
}
