1:struct HistoryList {
2:    /// Element ids: the row's toggle, the accordion, and each item's heading.
3:    toggle: &'static str,
4:    list: &'static str,
5:    item: &'static str,
6:    /// The row's label, after its count.
7:    singular: &'static str,
8:    plural: &'static str,
9:    /// What the row reads while expanded.
10:    back: &'static str,
11:    /// Where its items' task indices start in their element ids, so two lists
12:    /// never share one.
13:    id_base: usize,
14:    expanded: bool,
15:    /// The item opened in the accordion.
16:    open: Option<usize>,
17:    scroll: ScrollHandle,
18:    /// Counts the times it was expanded.
19:    opened: usize,
20:    /// Its tables collapse the steps leading up to the answer.
21:    collapse_steps: bool,
22:}
