24:impl HistoryList {
25:    fn toggle(&mut self) {
26:        self.expanded = !self.expanded;
27:        if self.expanded {
28:            self.opened += 1;
29:            // The latest are the likeliest to be looked for.
30:            self.scroll.scroll_to_bottom();
31:        }
32:    }
33:
34:    /// The row: "No …", "1 …", or "N …", which does nothing while `enabled`
35:    /// is false, and expands the list when clicked.
36:    fn render_row(
37:        &self,
38:        count: usize,
39:        enabled: bool,
40:        select: fn(&mut PromptMode) -> &mut HistoryList,
41:        cx: &mut Context<PromptMode>,
42:    ) -> AnyElement {
43:        let theme = cx.theme();
44:        let label = if self.expanded {
45:            self.back.to_string()
46:        } else {
47:            match count {
48:                0 => format!("No {}", self.plural),
49:                1 => format!("1 {}", self.singular),
50:                n => format!("{n} {}", self.plural),
51:            }
52:        };
53:        h_flex()
54:            .flex_none()
55:            .px_2()
56:            .py_0p5()
57:            .bg(theme.tab_bar)
58:            .border_b_1()
59:            .border_color(theme.border)
60:            .child(
61:                Button::new(self.toggle)
62:                    .ghost()
63:                    .xsmall()
64:                    .icon(if self.expanded {
65:                        IconName::ChevronDown
66:                    } else {
67:                        IconName::ChevronRight
68:                    })
69:                    .label(label)
70:                    .disabled(!enabled)
71:                    .on_click(cx.listener(move |this, _, _, cx| {
72:                        select(this).toggle();
73:                        cx.notify();
74:                    })),
75:            )
76:            .into_any_element()
77:    }
78:
79:    /// Every item, oldest first, as an accordion that scrolls.
80:    fn render_list(
81:        &self,
82:        tasks: &[PromptTask],
83:        select: fn(&mut PromptMode) -> &mut HistoryList,
84:        open_file: &OpenFile,
85:        steps_shown: &HashSet<usize>,
86:        cx: &mut Context<PromptMode>,
87:    ) -> AnyElement {
88:        let this = cx.entity().downgrade();
89:        let accordion = tasks.iter().enumerate().fold(
90:            Accordion::new(self.list).h_auto(),
91:            |accordion, (ix, task)| {
92:                let open = self.open == Some(ix);
93:                let task_ix = self.id_base + ix;
94:                accordion.item(|item| {
95:                    item.open(open)
96:                        .title(task_summary((self.item, ix), task_ix, task, cx))
97:                        // Closed items are not laid out.
98:                        .when(open, |item| {
99:                            item.child(
100:                                v_flex()
101:                                    .gap_3()
102:                                    .pt_1()
103:                                    .child(task_prompt(task_ix, task, open_file, cx))
104:                                    .child(output_table(
105:                                        task_ix,
106:                                        &task.reply,
107:                                        Some(open_file),
108:                                        self.collapse_steps
109:                                            .then(|| steps(task_ix, steps_shown, cx)),
110:                                        cx,
111:                                    )),
112:                            )
113:                        })
114:                })
115:            },
116:        );
117:        let accordion = accordion.on_toggle_click(move |open, _, cx| {
118:            this.update(cx, |this, cx| {
119:                select(this).open = open.first().copied();
120:                cx.notify();
121:            })
122:            .ok();
123:        });
124:        let list = div()
125:            .id(SharedString::from(format!("{}-scroll", self.list)))
126:            .size_full()
127:            .overflow_y_scroll()
128:            .track_scroll(&self.scroll)
129:            .p_4()
130:            .child(accordion);
131:        // Lets UI tests find the list; inert in normal builds.
132:        let list = gpui_kit::TestSupportExt::test_support(list);
133:        scroll_column::with_scroll_column(self.list, &self.scroll, list, true, None, cx)
134:    }
135:}
