#[cfg(test)]
mod perf_probe {
    use std::time::{Duration, Instant};

    use gpui_kit::component::Root;
    use gpui_kit::{AppContext as _, TestAppContext};

    use super::MainWindow;
    use crate::piton_syntax;
    use crate::project_directory::ProjectDirectory;

    #[gpui_kit::test]
    #[ignore]
    async fn probe_window(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
            super::bind_keys(cx);
        });
        let mut main = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| MainWindow::new(window, cx));
            main = Some(view.clone());
            Root::new(view, window, cx)
        });
        let main = main.unwrap();
        let handle: gpui_kit::AnyWindowHandle = window.into();
        cx.update(|cx| ProjectDirectory::set(env!("CARGO_MANIFEST_DIR").into(), cx));
        for _ in 0..40 {
            cx.run_until_parked();
            std::thread::sleep(Duration::from_millis(25));
        }
        let pm = main.read_with(cx, |main, _| main.prompt_mode.clone());
        let mut total = Duration::ZERO;
        for _ in 0..20 {
            cx.update_window(handle, |_, window, cx| {
                pm.update(cx, |_, cx| cx.notify());
                let start = Instant::now();
                window.draw(cx);
                total += start.elapsed();
            })
            .unwrap();
        }
        eprintln!("PROBE window: prompt mode notify -> frame {:?}", total / 20);
        let mut total = Duration::ZERO;
        for _ in 0..20 {
            cx.update_window(handle, |_, window, cx| {
                let start = Instant::now();
                window.draw(cx);
                total += start.elapsed();
            })
            .unwrap();
        }
        eprintln!("PROBE window: nothing notified -> frame {:?}", total / 20);
    }
}
